//! Interop tests against real Xray-core and sing-box VMess servers.
//!
//! These tests are ignored by default; the `REALITY interop (Linux)` CI job
//! starts the servers and targets and runs them with `--ignored`. Inputs:
//!
//! * `NC_VMESS_SERVERS`: `name=host:port:transport,...` with transport `tcp`
//!   or `ws` (WebSocket path `/vm`)
//! * `NC_VMESS_UUID`
//! * `NC_HTTP_TARGET`: plain HTTP/1.0 server serving `/payload.bin`
//!   generated by [`expected_payload`]

use std::io;
use std::net::SocketAddr;
use std::sync::Arc;
use std::time::Duration;

use engine_outbound::{TargetAddr, TcpDialer, TcpOutbound};
use outbound_vmess::{parse_uuid, Security, VmessOutbound};
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use transport_ws::{WsConnector, WsSettings};

const PAYLOAD_LEN: usize = 1_000_000;
const TIMEOUT: Duration = Duration::from_secs(60);

fn expected_payload() -> Vec<u8> {
    (0..PAYLOAD_LEN)
        .map(|i| ((i * 7 + 3) % 251) as u8)
        .collect()
}

fn env(name: &str) -> String {
    std::env::var(name).unwrap_or_else(|_| panic!("{name} must be set for interop tests"))
}

struct Server {
    name: String,
    host: String,
    port: u16,
    websocket: bool,
}

fn servers() -> Vec<Server> {
    env("NC_VMESS_SERVERS")
        .split(',')
        .map(|entry| {
            let (name, rest) = entry.split_once('=').expect("name=host:port:transport");
            let mut parts = rest.rsplitn(3, ':');
            let websocket = match parts.next().unwrap() {
                "tcp" => false,
                "ws" => true,
                other => panic!("unknown transport {other}"),
            };
            let port: u16 = parts.next().unwrap().parse().unwrap();
            let host = parts.next().unwrap().to_owned();
            Server {
                name: name.to_owned(),
                host,
                port,
                websocket,
            }
        })
        .collect()
}

fn outbound(server: &Server, security: Security) -> VmessOutbound {
    let uuid = parse_uuid(&env("NC_VMESS_UUID")).unwrap();
    let outbound = VmessOutbound::new(
        server.host.clone(),
        server.port,
        uuid,
        security,
        None,
        Arc::new(TcpDialer),
    )
    .unwrap();
    if !server.websocket {
        return outbound;
    }
    let settings = WsSettings {
        path: "/vm".to_owned(),
        host: String::new(),
        headers: Vec::new(),
    };
    outbound.with_websocket(WsConnector::new(&settings, &server.host).unwrap())
}

async fn fetch_payload(outbound: &VmessOutbound) -> io::Result<Vec<u8>> {
    let target = TargetAddr::from(env("NC_HTTP_TARGET").parse::<SocketAddr>().unwrap());
    let mut stream = outbound.connect(&target).await?;
    stream
        .write_all(b"GET /payload.bin HTTP/1.0\r\nHost: interop.test\r\n\r\n")
        .await?;
    stream.flush().await?;
    let mut response = Vec::new();
    stream.read_to_end(&mut response).await?;
    let split = response
        .windows(4)
        .position(|window| window == b"\r\n\r\n")
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "no HTTP header terminator"))?;
    let status = String::from_utf8_lossy(&response[..split]).to_string();
    if !(status.starts_with("HTTP/1.0 200") || status.starts_with("HTTP/1.1 200")) {
        return Err(io::Error::other(format!("unexpected status: {status}")));
    }
    Ok(response[split + 4..].to_vec())
}

#[tokio::test(flavor = "current_thread")]
#[ignore = "needs the REALITY interop CI environment"]
async fn downloads_through_every_server_and_cipher() {
    let expected = expected_payload();
    let mut failures = Vec::new();
    for server in servers() {
        for security in [Security::Aes128Gcm, Security::ChaCha20Poly1305] {
            let label = format!("{} {security:?}", server.name);
            let outbound = outbound(&server, security);
            match tokio::time::timeout(TIMEOUT, fetch_payload(&outbound)).await {
                Ok(Ok(body)) if body == expected => eprintln!("{label}: ok, {} bytes", body.len()),
                Ok(Ok(body)) => failures.push(format!("{label}: {} bytes differ", body.len())),
                Ok(Err(error)) => failures.push(format!("{label}: {error}")),
                Err(_) => failures.push(format!("{label}: timed out")),
            }
        }
    }
    assert!(failures.is_empty(), "failures:\n{}", failures.join("\n"));
}
